-- Phase 6: Life Updates. Generated by drizzle-kit, then hand-edited (README:
-- "hand-edit only the new file"). Hand edits: the sections validator function
-- (created before the table whose CHECK calls it), the posts reference index
-- moved ahead of the foreign key that needs it, and the triggers at the end.
-- Valid sections: an object of at most 20 keys (letters only, 1-40 chars),
-- each a string of 1-2,000 characters, 10,000 in total. The key list itself
-- is the API's (packages/domain), so adding a section needs no migration.
-- CASE guarantees jsonb_each never sees a non-object; NULL is never valid.
CREATE FUNCTION "paldora"."life_update_sections_valid"(sections jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$
  select case
    when sections is null or jsonb_typeof(sections) <> 'object' then false
    else
      (select count(*) from jsonb_each(sections)) <= 20
      and not exists (
        select 1 from jsonb_each(sections) as entry(key, value)
        where entry.key !~ '^[A-Za-z]{1,40}$'
           or jsonb_typeof(entry.value) <> 'string'
           or char_length(entry.value #>> '{}') not between 1 and 2000
      )
      and (
        select coalesce(sum(char_length(entry.value #>> '{}')), 0)
        from jsonb_each(sections) as entry(key, value)
      ) <= 10000
  end
$$;--> statement-breakpoint
