-- Audience immutability: a delivery can only be written in the transaction
-- that created its Life Update (whose created_at is that transaction's
-- timestamp), so no later transaction can add a Box.
CREATE FUNCTION "paldora"."life_update_deliveries_insert_guard"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM "paldora"."life_updates"
    WHERE "id" = NEW."life_update_id" AND "created_at" = transaction_timestamp()
  ) THEN
    RAISE EXCEPTION 'life_update_audience_immutable'
      USING ERRCODE = '23000', CONSTRAINT = 'life_update_audience_immutable';
  END IF;
  RETURN NEW;
END
$$;--> statement-breakpoint
CREATE TRIGGER "life_update_deliveries_insert_guard"
BEFORE INSERT ON "paldora"."life_update_deliveries"
FOR EACH ROW EXECUTE FUNCTION "paldora"."life_update_deliveries_insert_guard"();--> statement-breakpoint
-- Deliveries are never changed, and never removed directly: only a cascade
-- (Box deletion, or a Life Update purge) may remove one. A cascade runs
-- inside the referential-integrity trigger, so its trigger depth exceeds 1.
CREATE FUNCTION "paldora"."life_update_deliveries_immutable"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'life_update_audience_immutable'
    USING ERRCODE = '23000', CONSTRAINT = 'life_update_audience_immutable';
END
$$;--> statement-breakpoint
CREATE TRIGGER "life_update_deliveries_no_update"
BEFORE UPDATE OR DELETE ON "paldora"."life_update_deliveries"
FOR EACH ROW EXECUTE FUNCTION "paldora"."life_update_deliveries_immutable"();--> statement-breakpoint
CREATE FUNCTION "paldora"."life_updates_immutable_columns"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW."audience" IS DISTINCT FROM OLD."audience"
     OR NEW."author_user_id" IS DISTINCT FROM OLD."author_user_id"
     OR NEW."created_at" IS DISTINCT FROM OLD."created_at" THEN
    RAISE EXCEPTION 'life_update_audience_immutable'
      USING ERRCODE = '23000', CONSTRAINT = 'life_update_audience_immutable';
  END IF;
  RETURN NEW;
END
$$;--> statement-breakpoint
CREATE TRIGGER "life_updates_immutable_columns"
BEFORE UPDATE ON "paldora"."life_updates"
FOR EACH ROW EXECUTE FUNCTION "paldora"."life_updates_immutable_columns"();--> statement-breakpoint
-- At commit, every Life Update has a delivery (1-20 Boxes, or one only-me row).
CREATE FUNCTION "paldora"."life_updates_require_delivery"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM "paldora"."life_updates" WHERE "id" = NEW."id")
     AND NOT EXISTS (
       SELECT 1 FROM "paldora"."life_update_deliveries"
       WHERE "life_update_id" = NEW."id"
     ) THEN
    RAISE EXCEPTION 'life_update_requires_delivery'
      USING ERRCODE = '23000', CONSTRAINT = 'life_update_requires_delivery';
  END IF;
  RETURN NULL;
END
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER "life_updates_requires_delivery"
AFTER INSERT ON "paldora"."life_updates"
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION "paldora"."life_updates_require_delivery"();--> statement-breakpoint
-- At commit, every backing post belongs to a delivery (the reverse direction
-- of "exactly one backing post per delivery").
CREATE FUNCTION "paldora"."posts_life_update_require_delivery"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM "paldora"."posts" WHERE "id" = NEW."id")
     AND NOT EXISTS (
       SELECT 1 FROM "paldora"."life_update_deliveries"
       WHERE "post_id" = NEW."id"
     ) THEN
    RAISE EXCEPTION 'posts_life_update_requires_delivery'
      USING ERRCODE = '23000', CONSTRAINT = 'posts_life_update_requires_delivery';
  END IF;
  RETURN NULL;
END
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER "posts_life_update_requires_delivery"
AFTER INSERT ON "paldora"."posts"
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW WHEN (NEW."kind" = 'life_update')
EXECUTE FUNCTION "paldora"."posts_life_update_require_delivery"();--> statement-breakpoint
-- A post never changes kind: an ordinary post cannot become a backing post
-- without a delivery, and a backing post cannot shed its Life Update.
CREATE FUNCTION "paldora"."posts_kind_immutable"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'posts_kind_immutable'
    USING ERRCODE = '23000', CONSTRAINT = 'posts_kind_immutable';
END
$$;--> statement-breakpoint
CREATE TRIGGER "posts_kind_immutable"
BEFORE UPDATE OF "kind" ON "paldora"."posts"
FOR EACH ROW WHEN (OLD."kind" IS DISTINCT FROM NEW."kind")
EXECUTE FUNCTION "paldora"."posts_kind_immutable"();
